// Duas gravações de teste de 0,5 s (ffmpeg, libopus, mono, 48 kHz, 32 kbps), em base64: uma WebM comum e outra "ao vivo" (tamanhos desconhecidos, como o MediaRecorder do Chrome escreve).
export const OPUS_WEBM = "";
export const OPUS_WEBM_AO_VIVO = "";
export const bytesDe = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
